package za.ac.cput.controller; import org.springframework.web.bind.annotation.*; import za.ac.cput.domain.Register; import za.ac.cput.service.RegisterService; import java.util.List; @RestController @RequestMapping("/register") public class RegisterController{private final RegisterService service; public RegisterController(RegisterService service){this.service=service;} @PostMapping("/create") public Register create(@RequestBody Register x){return service.create(x);} @GetMapping("/read/{id}") public Register read(@PathVariable String id){return service.read(id);} @PutMapping("/update") public Register update(@RequestBody Register x){return service.update(x);} @DeleteMapping("/delete/{id}") public boolean delete(@PathVariable String id){return service.delete(id);} @GetMapping("/getAll") public List<Register> getAll(){return service.findAll();} }